mapper.select:

SELECT m.`id`, m.`title`, m.`chinese_title`, m.`cover`, m.`favorite` FROM `manga` m

    m.`user_id`=#{userId}
    AND m.`deleted`=#{deleted}
    AND m.`author` LIKE CONCAT('%', #{author}, '%')
    AND (m.`title` LIKE CONCAT('%', #{title}, '%') OR m.`chinese_title` LIKE CONCAT('%', #{title}, '%'))

        AND EXISTS (
            SELECT 1 FROM `manga_tag_relation` r
            INNER JOIN `manga_tag` t
                    ON t.`id` = r.`tag_id` AND t.`user_id` = #{userId}
            WHERE r.`manga_id` = m.`id` AND r.`tag_id` = #{tagId}
        )


ORDER BY m.`id` DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM `manga` m

    m.`user_id`=#{userId}
    AND m.`deleted`=#{deleted}
    AND m.`author` LIKE CONCAT('%', #{author}, '%')
    AND (m.`title` LIKE CONCAT('%', #{title}, '%') OR m.`chinese_title` LIKE CONCAT('%', #{title}, '%'))

        AND EXISTS (
            SELECT 1 FROM `manga_tag_relation` r
            INNER JOIN `manga_tag` t
                    ON t.`id` = r.`tag_id` AND t.`user_id` = #{userId}
            WHERE r.`manga_id` = m.`id` AND r.`tag_id` = #{tagId}
        )

SELECT `id` FROM `manga`
WHERE `deleted` = 1 AND `update_time` <= #{cutoff,jdbcType=TIMESTAMP}
ORDER BY `update_time`, `id`

SELECT * FROM `manga`
WHERE `id` = #{id}
  AND `deleted` = 1
  AND `update_time` <= #{cutoff,jdbcType=TIMESTAMP}
FOR UPDATE
